class ResourceManager {
public:
  // User-declared move constructor
  ResourceManager(ResourceManager&& rhs) noexcept { /* ... steal resources ... */ }

  // NO move assignment operator is declared.
  // The compiler will NOT generate one.
private:
  int* data_;
};

void example() {
  ResourceManager r1;
  ResourceManager r2(std::move(r1)); // OK: calls user-declared move ctor

  ResourceManager r3;
  // r3 = std::move(r2); // ERROR: move assignment operator is implicitly deleted
}
